 const candidates=[...strict,...queue,...watch].slice(0,10),empty=$('budgetTopEmpty'),table=$('budgetTopTable'),body=$('budgetTopBody'),mobile=$('budgetTopMobile');body.innerHTML='';mobile.innerHTML='';
 if(!candidates.length){empty.style.display='block';table.hidden=true;empty.textContent='현재는 실전 우선순위에 올릴 종목이 없습니다.';return}
 empty.style.display='none';table.hidden=false;candidates.forEach((x,i)=>{const v=beginnerVerdict(x),tier=candidateTier(x),isBuy=tier==='buy',tr=document.createElement('tr');tr.className=isBuy?'budget-row-buy':'budget-row-watch';const status=isBuy?(immediateAllowed(x)?'🔥 매수 후보':'📅 다음 장 관심'):(tier==='queue'?'⏳ 기준통과·위험한도 대기':'🟡 진입대기');tr.innerHTML=`<td><b>${i+1}위</b><small class="rank-status ${isBuy?'rank-buy':'rank-watch'}">${status}</small>${rankBadge(x)?`<small class="rank-move">${escapeText(rankBadge(x))}</small>`:''}</td><td><b>${escapeText(x.name)}</b><small>${escapeText(x.code)} · ${escapeText(x.sector||'')}</small></td><td><b>${Number(x.opportunity_score||0).toFixed(0)}점</b><small>${escapeText(x.opportunity_label||'')}</small></td><td>${escapeText(isBuy?v.text.replace(/^[^ ]+ /,''):(tier==='queue'?'종목 기준 통과 · 계좌 배정 대기':'조건 근접 · 대기'))}</td><td>${escapeText(x.tech||'')}</td><td>${fmt(x.entry_krw)}원</td><td><b>${isBuy?x.qty:'-' }${isBuy?'주':''}</b><small>${isBuy?fmt(x.invested_krw)+'원':'매수 전'}</small></td><td class="plus">${isBuy?'+'+fmt(x.expected_profit_krw)+'원':'-'}</td><td class="minus">${isBuy?fmt(x.expected_loss_krw)+'원':'-'}</td><td>${escapeText(x.buy_time||'-')}</td>`;body.appendChild(tr);const d=document.createElement('div');d.className=`budget-mini ${isBuy?'budget-mini-buy':'budget-mini-watch'}`;d.innerHTML=`<div><b>${isBuy?'🔥':'🟡'} ${i+1}. ${escapeText(x.name)}</b><span>${status} · 기회 ${Number(x.opportunity_score||0).toFixed(0)}점</span></div><div class="budget-mini-grid"><span>진입 <b>${fmt(x.entry_krw)}원</b></span><span>${isBuy?'수량':'손익비'} <b>${isBuy?x.qty+'주':'1:'+Number(x.rrr||0).toFixed(2)}</b></span><span>모멘텀 <b>${Number(x.momentum||0).toFixed(0)}점</b></span><span>전략 <b>${escapeText(x.tech||'-')}</b></span></div>${rankBadge(x)?`<div class="rank-move">${escapeText(rankBadge(x))}</div>`:''}<small>🕒 ${escapeText(x.buy_time||'-')} · ${escapeText(x.sector||'')}</small>`;mobile.appendChild(d)})
