l.querySelector('.time-stop').textContent=item.time_stop||'';const sp=item.split_plan||{};tpl.querySelector('.split-buy').textContent=(sp.buy_tranches||[]).length?(sp.buy_tranches||[]).map(x=>`${x.label} ${x.qty}주@${fmt(x.price_krw)}원`).join(' / '):(sp.summary||'현재 분할매수 없음');tpl.querySelector('.split-sell').textContent=(sp.sell_tranches||[]).length?(sp.sell_tranches||[]).map(x=>`${x.label} ${x.qty}주${x.price_krw?`@${fmt(x.price_krw)}원`:''}`).join(' / '):'현재 분할매도 없음';const fp=item.flow_proxy||{};tpl.querySelector('.flow-label').textContent=fp.label||'수급 프록시 없음';tpl.querySelector('.flow-reason').textContent=(fp.reason||'')+(fp.note?` · ${fp.note}`:'');const bt=item.backtest||{};tpl.querySelector('.backtest-label').textContent=bt.label||'백테스트 없음';tpl.querySelector('.backtest-detail').textContent=bt.trades?`유사신호 ${bt.trades}회 · 비용후 승률 ${bt.net_success_rate??bt.success_rate}% · 비용후 평균 ${pct(bt.net_avg_return_5d??bt.avg_return_5d)} · PF ${bt.net_profit_factor??bt.profit_factor??'-'} · WF ${bt.walk_forward_folds??0}폴드/${bt.oos_trades??0}건/${bt.oos_net_success_rate??'-'}% · Brier ${bt.wf_brier??'-'} · 보정오차 ${bt.wf_calibration_gap_pct??'-'}% · MC강건성 ${bt.robustness_score??'-'}점 · ${bt.walk_forward_label||''} · 신뢰계수 ${bt.reliability_factor??'-'} · 검증 ${bt.validation_score??0}점`:(bt.note||'과거 유사신호 없음');tpl.querySelector('.volume').textContent=compact(item.volume);tpl.querySelector('.avg-volume').textContent=compact(item.avg_volume20);tpl.querySelector('.rvol-quick').textContent=`${item.rvol||0}배`;tpl.querySelector('.trading-value').textContent=`${compact(item.trading_value_krw)}원`;
const al=tpl.querySelector('.attention-label'),as=tpl.querySelector('.attention-score'),ar=tpl.querySelector('.attention-reasons');al.textContent=item.attention_label||'⚪ 관심 보통';as.textContent=`관심점수 ${item.attention_score??0}점`;ar.textContent=(item.attention_reasons||[]).join(' · ')||'거래량·거래대금 특이 신호 없음';
tpl.querySelector('.outlook-label').textContent=`${item.outlook_label||'-'} (${item.outlook_score??'-'}점)`;tpl.querySelector('.outlook-summary').textContent=item.outlook_summary||'';const lp=item.long_term||{};tpl.querySelector('.long-action').textContent=`${lp.action||'-'} (${lp.score??'-'}점)`;tpl.querySelector('.long-plan').textContent=lp.qty>0?`장기예산 ${fmt(lp.budget_krw)}원 · 총 ${lp.qty}주 · `+(lp.tranches||[]).map(x=>`${x.label} ${x.qty}주@${fmt(x.price_krw)}원`).join(' / '):'현재 기준 장기 신규매수 수량 0주';
const hb=tpl.querySelector('.held-box');if(item.held_action){hb.hidden=false;tpl.querySelector('.held-action').textContent=item.held_action.action;tpl.querySelector('.held-pnl').textContent=`평단 ${fmt(item.held_price_krw)}원 · ${item.held_qty||0}주 · 손익 ${pct(item.held_action.pnl_pct)} (${fmt(item.held_action.pnl_krw)}원)`;tpl.querySelector('.held-reason').textContent=item.held_action.reason+(item.held_action.add_qty?` · 추가매수 최대 ${item.held_action.add_qty}주 검토`:'');tpl.querySelector('.loss-stage').textContent=`현재 단계: ${item.held_action.loss_stage||'-'}${item.held_action.trend_broken?' · 추세 약화/이탈':''}`;tpl.querySelector('.recovery-steps').innerHTML=(item.held_action.recovery_steps||[]).map((x,i)=>`<div>${i+1}. ${escapeText(x)}</div>`).join('');tpl.querySelector('.avg-recovery').textContent=item.held_action.pnl_pct<0?`현재가에서 평단 회복까지 약 +${Number(item.held_action.avg_recovery_pct||0).toFixed(1)}% 필요 · 본전 집착보다 손실 한도와 추세를 우선하세요.`:''}
