async function loadIssues(btn,body){
 if(btn.disabled)return;btn.disabled=true;const original=btn.textContent;btn.textContent='조회 중…';body.textContent='최근 공개 이슈를 불러오는 중입니다.';
 try{const headers={'Content-Type':'application/json'},pin=$('appPin').value.trim();if(pin)headers['X-App-Pin']=pin;const res=await fetch('/api/issues',{method:'POST',headers,body:JSON.stringify({code:btn.dataset.code,market:btn.dataset.market})});const out=await res.json();if(!res.ok||!out.ok)throw new Error(out.error||'이슈 조회 실패');const d=out.data||{},items=d.items||[];if(!items.length){body.textContent=d.error||'최근 이슈 데이터가 없습니다.';}else{body.innerHTML=`<div class="issue-summary"><b>${escapeText(d.news_label||'최근 이슈')}</b> · 뉴스 ${d.count}건 · 긍정 ${d.positive_count||0} / 위험 ${d.risk_count||0}</div>`+items.map(x=>`<div class="issue-item">${x.link?`<a href="${escapeText(x.link)}" target="_blank" rel="noopener">${escapeText(x.title)}</a>`:`<b>${escapeText(x.title)}</b>`}<small>${escapeText(x.quality_label||'')} · ${escapeText(x.publisher||'')}</small></div>`).join('')+`<small>${escapeText(d.note||'')}</small>`;}btn.textContent=out.cache_hit?'이슈 새로보기':'이슈 다시보기';}
 catch(e){body.textContent=`이슈 조회 오류: ${e.message}`;btn.textContent=original;}finally{btn.disabled=false}
}

async function loadFundamentals(btn,body){
 if(btn.disabled)return;btn.disabled=true;const original=btn.textContent;btn.textContent='조회 중…';body.textContent='실적 데이터를 불러오는 중입니다.';
 try{const headers={'Content-Type':'application/json'},pin=$('appPin').value.trim();if(pin)headers['X-App-Pin']=pin;const res=await fetch('/api/fundamentals',{method:'POST',headers,body:JSON.stringify({code:btn.dataset.code,market:btn.dataset.market})});const out=await res.json();if(!res.ok||!out.ok)throw new Error(out.error||'실적 조회 실패');const d=out.data||{};const money=v=>v===null||v===undefined?'-':compact(v);const ratio=v=>v===null||v===undefined?'-':`${(Number(v)*100).toFixed(1)}%`;const raw=v=>v===null||v===undefined?'-':Number(v).toFixed(1);body.innerHTML=`<div class="fund-grid"><div>매출<b>${escapeText(money(d.revenue))}</b></div><div>매출 성장률<b>${escapeText(ratio(d.revenue_growth))}</b></div><div>순이익<b>${escapeText(money(d.net_income))}</b></div><div>이익 성장률<b>${escapeText(ratio(d.earnings_growth))}</b></div><div>영업이익률<b>${escapeText(ratio(d.operating_margin))}</b></div><div>PER<b>${escapeText(raw(d.trailing_pe))}</b></div><div>시가총액<b>${escapeText(money(d.market_cap))}</b></div><div>52주 변화<b>${escapeText(ratio(d.fifty_two_week_change))}</b></div></div><div class="fund-quality ${d.quality_confirmed?'confirmed':'not-confirmed'}">${escapeText(d.quality_label||'')}</div>${d.earnings_risk?`<div class="earnings-risk">${escapeText(d.earnings_risk)}</div>`:''}<small>${escapeText(d.error||'Yahoo Finance 기반 · 제공되지 않는 항목은 - 로 표시')}</small>`;btn.textContent=out.cache_hit?'실적 새로보기':'실적 다시보기';}
 catch(e){body.textContent=`실적 조회 오류: ${e.message}`;btn.textContent=original;}finally{btn.disabled=false}
}

