function installSymbolPicker(inputId,boxId,marketId,onPick){
 const input=$(inputId),box=$(boxId),market=$(marketId);if(!input||!box)return;let timer=0,seq=0;
 const hide=()=>{box.hidden=true;box.innerHTML=''};
 const clearMeta=()=>{['selectedCode','selectedName','selectedType','selectedExchange','selectedSector','selectedSectorMajor','selectedSourceSector'].forEach(k=>delete input.dataset[k])};
 const run=()=>{const q=input.value.trim();if(q.length<1){hide();return}const mine=++seq;clearTimeout(timer);box.innerHTML='<div class="symbol-no-result">KRX·네이버·Yahoo 교차 검색 중…</div>';box.hidden=false;timer=setTimeout(async()=>{
  try{const h={},pin=$('appPin').value.trim();if(pin)h['X-App-Pin']=pin;const r=await fetch(`/api/symbols?q=${encodeURIComponent(q)}&market=${encodeURIComponent(market?.value||'AUTO')}`,{headers:h,cache:'no-store'}),d=await r.json();if(mine!==seq)return;if(!r.ok||!d.ok)throw new Error(d.error||'검색 실패');const items=d.items||[];box.innerHTML=items.length?items.map((x,i)=>`<button type="button" class="symbol-suggestion" data-si="${i}"><b>${escapeText(x.name)}</b><span>${escapeText(x.code)} · ${escapeText(x.type||'주식')}</span><small>${escapeText(x.market==='US'?'미국':'국내')} ${escapeText(x.exchange||'')}${x.sector?` · <span class="symbol-sector">🏷 ${escapeText(x.sector)}</span>`:''}</small></button>`).join(''):'<div class="symbol-no-result">검색 원본에서 일치 종목을 확인하지 못했습니다. 국내 종목은 6자리 코드로도 검색해 보세요.</div>';box.hidden=false;box.querySelectorAll('[data-si]').forEach(b=>b.onclick=()=>{const x=items[Number(b.dataset.si)];input.value=x.code;if(market)market.value=(x.type==='ETF'&&x.market==='KR'?'ETF':x.market);input.dataset.selectedName=x.name;input.dataset.selectedCode=x.code;input.dataset.selectedType=x.type||'';input.dataset.selectedExchange=x.exchange||'';input.dataset.selectedSector=x.sector||'';input.dataset.selectedSectorMajor=x.sector_major||'';input.dataset.selectedSourceSector=x.source_sector||'';hide();if(onPick)onPick(x)});
  }catch(e){if(mine===seq){box.innerHTML=`<div class="symbol-no-result">종목 검색 오류: ${escapeText(e.message)} · 잠시 후 다시 시도하거나 6자리 종목코드를 입력하세요.</div>`;box.hidden=false}}
 },140)};
 input.addEventListener('input',()=>{clearMeta();run()});input.addEventListener('focus',run);if(market)market.addEventListener('change',run);document.addEventListener('click',e=>{if(!box.contains(e.target)&&e.target!==input)hide()});
}
