 const oldId=currentAccountId(),next=String(prompt('새 개인 ID를 입력하세요.\n(6자 이상, 영문/숫자/-/_/.)',oldId)||'').trim().toLowerCase();
 if(!next||next===oldId)return;
 if(next.length<6){setAccountStatus('새 개인 ID는 6자 이상이어야 합니다.');return}
 if(!confirm(`${oldId} → ${next} 로 변경할까요?\n보유·관심·모으기 자료는 그대로 이전됩니다.`))return;
 try{const oldKey=accountLocalKey(),local=loadJson(oldKey,[]);const r=await fetch('/api/account/change-id',{method:'POST',headers:portfolioHeaders(),body:JSON.stringify({new_account_id:next})}),d=await r.json();if(!r.ok||!d.ok)throw new Error(d.error||'ID 변경 실패');$('accountId').value=d.account_id;saveSettings();const newKey=accountLocalKey();if(Array.isArray(local)&&local.length)saveJson(newKey,local);try{localStorage.removeItem(oldKey)}catch(e){}accountConnected=true;setAccountStatus(`✅ 개인 ID가 ${d.account_id}(으)로 변경되었습니다. 휴대폰/PC도 새 ID로 연결하세요.`,true);await portfolioCloudLoad()}catch(e){setAccountStatus(`ID 변경 실패: ${e.message}`)}
